// 后台管理 API
// 绑定：KV 命名空间变量名 KV；环境变量（加密）ADMIN
// 路由：/api/admin/<action>
const STATE_KEY = 'state';
const COOKIE = 'cs5_admin';
const SESSION_TTL = 7 * 24 * 3600;
const enc = new TextEncoder();
const dec = new TextDecoder();

const b64u = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const fromB64u = (s) => {
	const t = s.replace(/-/g, '+').replace(/_/g, '/');
	return Uint8Array.from(atob(t + '='.repeat((4 - t.length % 4) % 4)), (c) => c.charCodeAt(0));
};
const json = (data, status = 200, headers = {}) => new Response(JSON.stringify(data), {
	status, headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...headers },
});

// ---------- 加密 / 会话 ----------
async function hmac(secret, text) {
	const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
	return b64u(await crypto.subtle.sign('HMAC', key, enc.encode(text)));
}
async function aesKey(secret) {
	const raw = await crypto.subtle.digest('SHA-256', enc.encode('cpi-kv-token:' + secret));
	return crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
}
async function encryptToken(token, secret) {
	const iv = crypto.getRandomValues(new Uint8Array(12));
	const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await aesKey(secret), enc.encode(token));
	return b64u(iv) + '.' + b64u(ct);
}
async function decryptToken(blob, secret) {
	const [iv, ct] = String(blob || '').split('.');
	try {
		return dec.decode(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: fromB64u(iv) }, await aesKey(secret), fromB64u(ct)));
	} catch {
		throw new Error('令牌解密失败（ADMIN 改过？请删除该账号后重新添加）');
	}
}
function safeEqual(a, b) {
	if (a.length !== b.length) return false;
	let r = 0;
	for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
	return r === 0;
}
async function makeSession(secret) {
	const exp = Math.floor(Date.now() / 1000) + SESSION_TTL;
	return exp + '.' + await hmac(secret, 'session:' + exp);
}
async function checkSession(request, secret) {
	const cookie = request.headers.get('Cookie') || '';
	const m = cookie.match(new RegExp('(?:^|;\\s*)' + COOKIE + '=([^;]+)'));
	if (!m) return false;
	const [exp, sig] = m[1].split('.');
	if (!exp || !sig || Number(exp) < Date.now() / 1000) return false;
	return safeEqual(sig, await hmac(secret, 'session:' + exp));
}

// ---------- KV 状态 ----------
async function readState(env) {
	let st = {};
	try { st = JSON.parse(await env.KV.get(STATE_KEY) || '{}') || {}; } catch { }
	return { accounts: Array.isArray(st.accounts) ? st.accounts : [], nodes: Array.isArray(st.nodes) ? st.nodes : [] };
}
const writeState = (env, st) => env.KV.put(STATE_KEY, JSON.stringify(st));
const publicState = (st) => ({
	accounts: st.accounts.map(({ token, ...rest }) => rest),
	nodes: st.nodes,
});

// ---------- Cloudflare API ----------
async function cf(token, path, init = {}) {
	const res = await fetch('https://api.cloudflare.com/client/v4/' + path, {
		...init, headers: { Authorization: 'Bearer ' + token, ...(init.headers || {}) },
	});
	let data = null;
	try { data = await res.json(); } catch { }
	if (!res.ok || !data || data.success === false) {
		const msg = data?.errors?.map((e) => (e.code ? e.code + ' ' : '') + e.message).join('; ') || 'HTTP ' + res.status;
		const err = new Error(msg);
		err.status = res.status;
		throw err;
	}
	return data.result;
}

function normalizeUrl(value) {
	try {
		const raw = String(value || '').trim();
		const u = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw);
		if (!/^https?:$/.test(u.protocol) || !/[.:]/.test(u.hostname)) return '';
		return u.origin;
	} catch { return ''; }
}

async function loadScript() {
	return NODE_CODE;
}

async function uploadScript(token, accountId, name, code) {
	const form = new FormData();
	form.append('metadata', new Blob([JSON.stringify({ main_module: 'worker.js', compatibility_date: '2024-09-23' })], { type: 'application/json' }));
	form.append('worker.js', new Blob([code], { type: 'application/javascript+module' }), 'worker.js');
	await cf(token, `accounts/${accountId}/workers/scripts/${name}`, { method: 'PUT', body: form });
}

async function ensureSubdomain(token, accountId) {
	try {
		const r = await cf(token, `accounts/${accountId}/workers/subdomain`);
		if (r?.subdomain) return r.subdomain;
	} catch (e) { if (e.status !== 404) throw e; }
	const want = 'cs5' + Math.random().toString(36).slice(2, 10);
	const r = await cf(token, `accounts/${accountId}/workers/subdomain`, {
		method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ subdomain: want }),
	});
	return r?.subdomain || want;
}

async function deployToAccount(env, request, st, acc, name, secret, code) {
	const token = await decryptToken(acc.token, secret);
	await uploadScript(token, acc.accountId, name, code);
	const sub = acc.subdomain || await ensureSubdomain(token, acc.accountId);
	acc.subdomain = sub;
	await cf(token, `accounts/${acc.accountId}/workers/scripts/${name}/subdomain`, {
		method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enabled: true, previews_enabled: false }),
	});
	const url = `https://${name}.${sub}.workers.dev`;
	const now = new Date().toISOString();
	const existing = st.nodes.find((n) => n.url === url);
	if (existing) Object.assign(existing, { source: 'deployed', accountRef: acc.id, script: name, updatedAt: now });
	else st.nodes.push({ url, enabled: true, source: 'deployed', accountRef: acc.id, script: name, deployedAt: now, updatedAt: now });
	return url;
}

// ---------- 路由 ----------
async function handleAdmin(request, env, action) {
	const secret = env.ADMIN;
	if (!secret || String(secret).length < 8) return json({ ok: false, error: '未设置 ADMIN 环境变量（至少 8 位）' }, 500);
	if (!env.KV) return json({ ok: false, error: '未绑定 KV 命名空间（变量名必须是 KV）' }, 500);

	const method = request.method;
	const body = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(method) ? await request.json().catch(() => ({})) : {};

	// 同源校验（防 CSRF）
	if (method !== 'GET') {
		const origin = request.headers.get('Origin');
		if (origin && origin !== new URL(request.url).origin) return json({ ok: false, error: 'bad origin' }, 403);
	}

	if (action === 'login' && method === 'POST') {
		const ok = safeEqual(await hmac(secret, 'pw:' + String(body.password || '')), await hmac(secret, 'pw:' + secret));
		if (!ok) {
			await new Promise((r) => setTimeout(r, 800));
			return json({ ok: false, error: '密码错误' }, 401);
		}
		return json({ ok: true }, 200, { 'Set-Cookie': `${COOKIE}=${await makeSession(secret)}; Path=/api/admin; HttpOnly; Secure; SameSite=Strict; Max-Age=${SESSION_TTL}` });
	}
	if (action === 'logout') {
		return json({ ok: true }, 200, { 'Set-Cookie': `${COOKIE}=; Path=/api/admin; HttpOnly; Secure; SameSite=Strict; Max-Age=0` });
	}
	if (!await checkSession(request, secret)) return json({ ok: false, error: 'unauthorized' }, 401);

	try {
		const st = await readState(env);

		// 用量统计：Cloudflare 免费版按 UTC 日计算 10 万次（每天 08:00 北京时间重置）
		if (action === 'usage' && method === 'GET') {
			const now = new Date();
			const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())).toISOString();
			const end = now.toISOString();
			const query = 'query($a:string!,$s:string!,$e:string!){viewer{accounts(filter:{accountTag:$a}){workersInvocationsAdaptive(limit:1000,filter:{datetime_geq:$s,datetime_leq:$e}){sum{requests errors}dimensions{scriptName}}}}}';
			const results = await Promise.all(st.accounts.map(async (acc) => {
				try {
					const token = await decryptToken(acc.token, secret);
					const res = await fetch('https://api.cloudflare.com/client/v4/graphql', {
						method: 'POST',
						headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
						body: JSON.stringify({ query, variables: { a: acc.accountId, s: start, e: end } }),
					});
					const data = await res.json().catch(() => null);
					if (!res.ok || !data || (data.errors && data.errors.length)) {
						const msg = data?.errors?.map((e) => e.message).join('; ') || 'HTTP ' + res.status;
						return { id: acc.id, error: /auth|permission|not authorized/i.test(msg) ? '令牌缺少「账户分析 · 读取」权限' : msg };
					}
					const rows = data.data?.viewer?.accounts?.[0]?.workersInvocationsAdaptive || [];
					const scripts = {};
					let total = 0, errors = 0;
					for (const r of rows) {
						const name = r.dimensions?.scriptName || '?';
						const n = r.sum?.requests || 0;
						scripts[name] = (scripts[name] || 0) + n;
						total += n;
						errors += r.sum?.errors || 0;
					}
					return { id: acc.id, total, errors, scripts };
				} catch (e) {
					return { id: acc.id, error: String(e?.message || e) };
				}
			}));
			return json({ ok: true, since: start, at: end, limit: Number(env.DAILY_LIMIT) || 100000, usage: results });
		}

		if (action === 'state' && method === 'GET') return json({ ok: true, ...publicState(st) });

		// 添加账号：校验令牌并取得账号列表
		if (action === 'accounts' && method === 'POST') {
			const token = String(body.token || '').trim();
			if (!/^[\w-]{20,}$/.test(token)) return json({ ok: false, error: '令牌格式不正确' }, 400);
			let list;
			if (body.accountId) {
				if (!/^[0-9a-f]{32}$/.test(body.accountId)) return json({ ok: false, error: 'Account ID 格式不正确' }, 400);
				await cf(token, `accounts/${body.accountId}/workers/scripts`); // 验证有 Workers 权限
				list = [{ id: body.accountId, name: body.label || body.accountId }];
			} else {
				list = await cf(token, 'accounts');
				if (!list?.length) return json({ ok: false, error: '令牌下没有账号。请给令牌加「账户设置:读取」权限，或手动填写 Account ID' }, 400);
			}
			const added = [];
			for (const a of list) {
				if (st.accounts.some((x) => x.accountId === a.id)) continue;
				const acc = {
					id: crypto.randomUUID(), label: String(body.label || a.name || '').slice(0, 60), accountId: a.id, accountName: a.name || '',
					token: await encryptToken(token, secret), tokenTail: token.slice(-4), addedAt: new Date().toISOString(),
				};
				st.accounts.push(acc);
				added.push(acc.accountName || acc.accountId);
			}
			await writeState(env, st);
			return json({ ok: true, added, ...publicState(st) });
		}

		const accMatch = action.match(/^accounts\/([\w-]+)$/);
		if (accMatch && method === 'DELETE') {
			st.accounts = st.accounts.filter((a) => a.id !== accMatch[1]);
			await writeState(env, st);
			return json({ ok: true, ...publicState(st) });
		}

		// 部署（一次一个账号，避免单次请求子请求数超限）
		if (action === 'deploy' && method === 'POST') {
			const acc = st.accounts.find((a) => a.id === body.account);
			if (!acc) return json({ ok: false, error: '账号不存在' }, 404);
			const name = String(body.name || 'check-node').toLowerCase();
			if (!/^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/.test(name)) return json({ ok: false, error: 'Worker 名称只能包含小写字母、数字和 -' }, 400);
			const url = await deployToAccount(env, request, st, acc, name, secret, await loadScript(env, request));
			await writeState(env, st);
			return json({ ok: true, url, ...publicState(st) });
		}

		// 更新节点代码（一次一个节点）
		if (action === 'redeploy' && method === 'POST') {
			const node = st.nodes.find((n) => n.url === body.url && n.source === 'deployed');
			const acc = node && st.accounts.find((a) => a.id === node.accountRef);
			if (!node || !acc) return json({ ok: false, error: '找不到节点或其账号（手动添加的节点无法更新）' }, 404);
			await uploadScript(await decryptToken(acc.token, secret), acc.accountId, node.script, await loadScript(env, request));
			node.updatedAt = new Date().toISOString();
			await writeState(env, st);
			return json({ ok: true, ...publicState(st) });
		}

		if (action === 'nodes') {
			const url = normalizeUrl(body.url);
			if (!url) return json({ ok: false, error: '节点地址不正确' }, 400);
			const node = st.nodes.find((n) => n.url === url);
			if (method === 'POST') {
				if (node) return json({ ok: false, error: '节点已存在' }, 409);
				st.nodes.push({ url, enabled: true, source: 'manual', deployedAt: new Date().toISOString() });
			} else if (method === 'PATCH') {
				if (!node) return json({ ok: false, error: '节点不存在' }, 404);
				if (typeof body.enabled === 'boolean') node.enabled = body.enabled;
				if (typeof body.note === 'string') node.note = body.note.slice(0, 60);
			} else if (method === 'DELETE') {
				if (!node) return json({ ok: false, error: '节点不存在' }, 404);
				if (body.undeploy && node.source === 'deployed') {
					const acc = st.accounts.find((a) => a.id === node.accountRef);
					if (acc) {
						try {
							await cf(await decryptToken(acc.token, secret), `accounts/${acc.accountId}/workers/scripts/${node.script}`, { method: 'DELETE' });
						} catch (e) { if (e.status !== 404) throw e; }
					}
				}
				st.nodes = st.nodes.filter((n) => n.url !== url);
			} else {
				return json({ ok: false, error: 'method not allowed' }, 405);
			}
			await writeState(env, st);
			return json({ ok: true, ...publicState(st) });
		}

		return json({ ok: false, error: 'not found: ' + action }, 404);
	} catch (error) {
		return json({ ok: false, error: String(error?.message || error) }, 500);
	}
}

// ==================== 路由 ====================
async function enabledNodes(env) {
	const fromEnv = String(env.CHECK_NODES || '').split(/[\s,，;；]+/).filter(Boolean);
	let fromKv = [];
	try {
		const st = JSON.parse((await env.KV?.get(STATE_KEY, { cacheTtl: 60 })) || '{}');
		fromKv = (st.nodes || []).filter((n) => n && n.enabled && n.url).map((n) => n.url);
	} catch { }
	return [...new Set([...fromEnv, ...fromKv])];
}

async function cachedLocations(request, ctx) {
	const cache = caches.default;
	const key = new Request(new URL('/locations', request.url).toString());
	let res = await cache.match(key);
	if (!res) {
		const up = await fetch('https://speed.cloudflare.com/locations', { headers: { Referer: 'https://speed.cloudflare.com/' } });
		res = new Response(up.body, { status: up.status, headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'public, max-age=86400', 'Access-Control-Allow-Origin': '*' } });
		if (up.ok) ctx.waitUntil(cache.put(key, res.clone()));
	}
	return res;
}

const html = (body, extra = {}) => new Response(body, { headers: { 'Content-Type': 'text/html; charset=utf-8', ...extra } });

export default {
	async fetch(request, env, ctx) {
		const url = new URL(request.url);
		const path = url.pathname.replace(/\/+$/, '') || '/';

		if (path === '/') {
			const nodes = await enabledNodes(env);
			const page = INDEX_HTML.replace('__CHECK_NODES__', JSON.stringify(nodes).replace(/</g, '\\u003c'));
			return html(page, { 'Cache-Control': 'no-cache' });
		}
		if (path === '/admin' || path === '/admin.html') {
			return html(ADMIN_HTML, { 'Cache-Control': 'no-store', 'X-Robots-Tag': 'noindex', 'X-Frame-Options': 'DENY' });
		}
		if (path.startsWith('/api/admin/')) return handleAdmin(request, env, path.slice('/api/admin/'.length));
		if (path === '/api/nodes') return json({ nodes: await enabledNodes(env) }, 200, { 'Access-Control-Allow-Origin': '*' });
		if (path === '/locations') return cachedLocations(request, ctx);
		if (path === '/node.js') return new Response(NODE_CODE, { headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
		return new Response('Not Found', { status: 404 });
	}
};
